-- ═══ 2. CHECK constraints ════════════════════════════════════════════════════
ALTER TABLE "order_note" ADD CONSTRAINT "order_note_body_check"
  CHECK (char_length(btrim("body")) BETWEEN 1 AND 2000);
ALTER TABLE "notification" ADD CONSTRAINT "notification_template_check"
  CHECK ("template" IN ('order.placed_cod', 'order.confirmed', 'order.shipped', 'order.cancelled'));
ALTER TABLE "notification" ADD CONSTRAINT "notification_error_check"
  CHECK (("status" = 'FAILED') = ("error" IS NOT NULL));
-- The codes are CANCEL_REASONS in @sanea/shared (a test compares the lists).
ALTER TABLE "order_status_event" ADD CONSTRAINT "order_status_event_reason_check"
  CHECK ((("to_status" = 'CANCELLED') = ("reason" IS NOT NULL))
     AND ("reason" IS NULL OR "reason" IN ('CUSTOMER_REQUESTED', 'CUSTOMER_UNREACHABLE',
       'SUSPECTED_FRAUD', 'OUT_OF_STOCK', 'ADDRESS_UNSERVICEABLE', 'OTHER',
       'PAYMENT_NOT_COMPLETED', 'NOT_CONFIRMED_IN_WINDOW', 'PAID_NO_STOCK')));
ALTER TABLE "order_status_event" ADD CONSTRAINT "order_status_event_other_note_check"
  CHECK ("reason" IS DISTINCT FROM 'OTHER' OR btrim(coalesce("note", '')) <> '');

-- ═══ 3. Append-only order notes (D-057) ═════════════════════════════════════
CREATE TRIGGER "order_note_append_only"
  BEFORE UPDATE OR DELETE ON "order_note"
  FOR EACH ROW EXECUTE FUNCTION "reject_append_only_change"();
CREATE TRIGGER "order_note_no_truncate"
  BEFORE TRUNCATE ON "order_note"
  FOR EACH STATEMENT EXECUTE FUNCTION "reject_append_only_change"();
